const inputData = $input.first().json;
const requestData = inputData.body || inputData;

if (!requestData.company_id) {
  throw new Error('company_id is required');
}

return [{
  json: {
    company_id: requestData.company_id,
    company_name: requestData.company_name || '',
    company_website: requestData.company_website || ''
  }
}];

// Merge enrichment data from all sources
const apolloData = $node['Apollo.io Enrichment'].json || {};
const clearbitData = $node['Clearbit Enrichment'].json || {};
const hunterData = $node['Hunter.io Email Search'].json || {};
const companyId = $node['Validate Input'].json.company_id;

const enrichedData = {
  company_id: companyId,
  linkedin_url: apolloData.linkedin_url || clearbitData.linkedin?.handle || null,
  linkedin_followers: clearbitData.linkedin?.followers || null,
  crunchbase_url: clearbitData.crunchbase?.handle || null,
  twitter_handle: clearbitData.twitter?.handle || null,
  twitter_followers: clearbitData.twitter?.followers || null,
  annual_revenue_usd: clearbitData.metrics?.annualRevenue || apolloData.estimated_annual_revenue || null,
  employee_growth_rate: clearbitData.metrics?.employeesGrowth || null,
  tech_stack: clearbitData.tech || [],
  company_type: clearbitData.type || null,
  data_sources: JSON.stringify({
    apollo: !!apolloData.name,
    clearbit: !!clearbitData.name,
    hunter: !!hunterData.data
  }),
  enrichment_date: new Date().toISOString()
};

// Extract email patterns from Hunter
const emails = [];
if (hunterData.data && hunterData.data.emails) {
  for (const email of hunterData.data.emails.slice(0, 10)) {
    emails.push({
      company_id: companyId,
      full_name: `${email.first_name} ${email.last_name}`,
      title: email.position || null,
      email: email.value,
      linkedin_url: email.linkedin || null,
      source: 'Hunter.io',
      confidence_score: email.confidence / 100,
      verified: email.verification?.status === 'valid'
    });
  }
}

return [{
  json: {
    enrichment: enrichedData,
    contacts: emails
  }
}];
